  else if(preview!=null){val p=preview!!;stickyHeader{Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text("وضع معاينة إدارية · قراءة فقط",fontWeight=FontWeight.Bold);Text("لا يمكن تنفيذ عمليات باسم المستخدم.");TextButton({preview=null}){Text("إنهاء المعاينة")}}}};item{val profile=p.getJSONObject("profile");RelaxiaAvatar(profile.optString("display_name"),profile.optInt("frame"),72,profile.optString("avatar_url"));Text(profile.optString("display_name"),style=MaterialTheme.typography.titleLarge);Text(profile.optString("username"));Text(profile.optString("bio"));Text(if(profile.optBoolean("creator"))"صلاحية النشر مفعلة"else"حساب مستخدم");Text("الخدمات والحجوزات والمزايا المعروضة تعكس بيانات الخادم.")};items(p.list("services")){r->AdminDataCard(r.optString("title"),"السعر: ${r.optLong("price_cents")} · ${r.optInt("duration_minutes")} دقيقة")};items(p.list("bookings")){r->AdminDataCard("حجز ${r.optString("id")}",r.optString("status"))};item{p.optJSONObject("wallet")?.let{Text("الرصيد: ${it.optLong("balance_cents")} · المحجوز: ${it.optLong("reserved_cents")}")};val c=p.getJSONObject("communication");Text("حالات التواصل فقط: ${c.optInt("sent")} مرسلة · ${c.optInt("received")} مستلمة · ${c.optInt("read")} مقروءة");Text("محتوى المحادثات غير متاح للمعاينة.")}}
