    "الموافقات المالية"->{items(data.list()){r->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text(r.optString("path"));Text(r.optString("reason"));Text("الحالة: "+r.optString("status"));Text("صاحب الطلب: ${r.optInt("requester_id")} · الحساب: ${r.optInt("target_user_id")}");Text(r.optJSONObject("payload")?.toString(2)?:"");if(r.optString("status")=="pending"&&r.optInt("requester_id")!=ownerId&&r.optInt("target_user_id")!=ownerId&&can("finance.approve"))listOf("approve" to "موافقة مستقلة","reject" to "رفض").forEach{(action,title)->TextButton({ask(title){v->post("/api/admin/control/approvals",JSONObject().put("id",r.getString("id")).put("action",action).put("reason",v["reason"]))}}){Text(title)}};if(r.optString("status")=="approved"&&r.isNull("used_at")&&r.optInt("requester_id")==ownerId)TextButton({ask("تنفيذ العملية المعتمدة"){_->post(r.getString("path"),JSONObject(r.getJSONObject("payload").toString()).put("approval_id",r.getString("id")))}}){Text("تنفيذ مرة واحدة")}}}}}
